predicate OrderedGreedy(sizes: seq<nat>, budget: int, decisions: seq<bool>) {
  |sizes| == |decisions| &&
  (forall i: int :: 0 <= i < |sizes| ==>
    (decisions[i] <==>
     IncludedTotal(sizes[..i], decisions[..i]) + sizes[i] <= budget))
}

method Pack(sizes: seq<nat>, budget: int) returns (decisions: seq<bool>, total: nat)
  ensures OrderedGreedy(sizes, budget, decisions)
  ensures total == IncludedTotal(sizes, decisions)
  ensures budget >= 0 ==> total <= budget
  ensures budget < 0 ==> total == 0
{
  decisions := [];
  total := 0;
  var i := 0;
  while i < |sizes|
    invariant 0 <= i <= |sizes|
    invariant |decisions| == i
    invariant total == IncludedTotal(sizes[..i], decisions)
    invariant budget >= 0 ==> total <= budget
    invariant budget < 0 ==> total == 0
    invariant forall j: int :: 0 <= j < i ==>
      (decisions[j] <==>
       IncludedTotal(sizes[..j], decisions[..j]) + sizes[j] <= budget)
    decreases |sizes| - i
  {
    ghost var previous := decisions;
    ghost var previousTotal := total;
    var fits := total + sizes[i] <= budget;
    decisions := decisions + [fits];
    if fits { total := total + sizes[i]; }
    assert decisions[..i] == previous;
    assert sizes[..i+1][..i] == sizes[..i];
    assert IncludedTotal(sizes[..i+1], decisions) ==
      previousTotal + (if fits then sizes[i] else 0);
    forall j: int | 0 <= j < i + 1
      ensures decisions[j] <==>
        IncludedTotal(sizes[..j], decisions[..j]) + sizes[j] <= budget
    {
      if j < i {
        assert decisions[..j] == previous[..j];
      } else {
        assert j == i;
        assert decisions[..j] == previous;
      }
    }
    i := i + 1;
  }
  assert i == |sizes|;
  assert sizes[..i] == sizes;
}

lemma GreedyConcat(a: seq<nat>, b: seq<nat>, x: seq<bool>, y: seq<bool>, budget: int)
  requires OrderedGreedy(a, budget, x)
  requires OrderedGreedy(b, budget - IncludedTotal(a, x), y)
  ensures OrderedGreedy(a + b, budget, x + y)
{
  forall i: int | 0 <= i < |a + b|
    ensures (x + y)[i] <==>
      IncludedTotal((a + b)[..i], (x + y)[..i]) + (a + b)[i] <= budget
  {
    if i < |a| {
      assert (a + b)[..i] == a[..i];
      assert (x + y)[..i] == x[..i];
    } else {
      var k := i - |a|;
      assert (a + b)[..i] == a + b[..k];
      assert (x + y)[..i] == x + y[..k];
      TotalConcat(a, b[..k], x, y[..k]);
    }
  }
}

ghost predicate Walk(es: seq<Edge>, p: seq<int>) {
  |p| >= 2 && forall i :: 0 <= i < |p|-1 ==> Edge(p[i], p[i+1]) in es
}

ghost predicate Reach(es: seq<Edge>, s: int, v: int) {
  exists p: seq<int> :: Walk(es,p) && p[0] == s && p[|p|-1] == v
}

method Compute(es: seq<Edge>, s: int) returns (reached: set<int>)
  ensures forall v :: v in reached <==> Reach(es,s,v)
{
  reached := Expand(es,{s});
  forall v | v in reached
    ensures Reach(es,s,v)
  {
    assert Edge(s,v) in es;
    assert Walk(es,[s,v]);
  }
  var added: set<int> := {};
  while true
    invariant reached <= Vertices(es)
    invariant forall v :: v in reached ==> Reach(es,s,v)
    invariant forall v :: Edge(s,v) in es ==> v in reached
    decreases Vertices(es) - reached
  {
    added := Expand(es,reached);
    if added <= reached { break; }
    forall v | v in added - reached
      ensures Reach(es,s,v)
    {
      var u :| u in reached && Edge(u,v) in es;
      PathExtension(es,s,u,v);
    }
    assert reached < reached + added;
    assert Vertices(es) - (reached + added) < Vertices(es) - reached;
    reached := reached + added;
  }
  assert forall u,v :: u in reached && Edge(u,v) in es ==> v in reached by {
    forall u,v | u in reached && Edge(u,v) in es
      ensures v in reached
    { assert v in added; }
  }
  forall v | Reach(es,s,v)
    ensures v in reached
  {
    var p :| Walk(es,p) && p[0] == s && p[|p|-1] == v;
    ClosedWalk(es,p,reached);
  }
}

lemma PathExtension(es: seq<Edge>, s: int, u: int, v: int)
  requires Reach(es,s,u) && Edge(u,v) in es
  ensures Reach(es,s,v)
{
  var p :| Walk(es,p) && p[0] == s && p[|p|-1] == u;
  var q := p + [v];
  assert Walk(es,q);
}

lemma ClosedWalk(es: seq<Edge>, p: seq<int>, reached: set<int>)
  requires Walk(es,p)
  requires forall v :: Edge(p[0],v) in es ==> v in reached
  requires forall u,v :: u in reached && Edge(u,v) in es ==> v in reached
  ensures p[|p|-1] in reached
  decreases |p|
{
  if |p| == 2 {
    assert Edge(p[0],p[1]) in es;
  } else {
    var q := p[..|p|-1];
    assert Walk(es,q);
    ClosedWalk(es,q,reached);
    assert Edge(p[|p|-2],p[|p|-1]) in es;
  }
}

predicate Occurrence(t: seq<int>, p: seq<int>, left: bool, right: bool, i: int) {
  0 <= i && i + |p| <= |t| && t[i..i + |p|] == p &&
  (!left || i == 0 || !AsciiWord(t[i-1])) &&
  (!right || i + |p| == |t| || !AsciiWord(t[i + |p|]))
}

ghost predicate HasOccurrence(t: seq<int>, p: seq<int>, left: bool, right: bool) {
  exists i: int :: Occurrence(t, p, left, right, i)
}

function Violations(flags: seq<bool>): seq<bool>
  requires |flags| % 2 == 0
  decreases |flags|
{
  if |flags| == 0 then []
  else [flags[0] && !flags[1]] + Violations(flags[2..])
}

method Find(t: seq<int>, p: seq<int>, left: bool, right: bool) returns (found: bool)
  ensures found <==> HasOccurrence(t, p, left, right)
{
  var i: int := 0;
  while i + |p| <= |t|
    invariant 0 <= i <= |t| + 1
    invariant forall j: int | 0 <= j < i && j + |p| <= |t| :: !Occurrence(t,p,left,right,j)
    decreases |t| + 1 - i
  {
    if t[i..i + |p|] == p &&
       (!left || i == 0 || !AsciiWord(t[i-1])) &&
       (!right || i + |p| == |t| || !AsciiWord(t[i + |p|])) {
      assert Occurrence(t, p, left, right, i);
      assert HasOccurrence(t, p, left, right) by {
        assert exists j: int :: Occurrence(t, p, left, right, j);
      }
      return true;
    }
    assert !Occurrence(t,p,left,right,i);
    i := i + 1;
  }
  return false;
}

lemma PolicyExact(flags: seq<bool>)
  requires |flags| % 2 == 0
  ensures |Violations(flags)| * 2 == |flags|
  ensures forall i: int | 0 <= i < |Violations(flags)| ::
    Violations(flags)[i] == (flags[2*i] && !flags[2*i+1])
  ensures IsRed(flags) <==> (exists i: int | 0 <= i < |flags| / 2 :: flags[2*i] && !flags[2*i+1])
  decreases |flags|
{
  if |flags| > 0 {
    PolicyExact(flags[2..]);
    if IsRed(flags) {
      if flags[0] && !flags[1] {
        assert exists i: int | 0 <= i < |flags| / 2 :: flags[2*i] && !flags[2*i+1] by {
          assert 0 < |flags| / 2;
          assert flags[2*0] && !flags[2*0+1];
        }
      } else {
        assert IsRed(flags[2..]);
        var j: int :| 0 <= j < |flags[2..]| / 2 && flags[2..][2*j] && !flags[2..][2*j+1];
        assert 0 <= j+1 < |flags| / 2;
        assert flags[2*(j+1)] && !flags[2*(j+1)+1];
      }
    }
    if exists i: int | 0 <= i < |flags| / 2 :: flags[2*i] && !flags[2*i+1] {
      var i: int :| 0 <= i < |flags| / 2 && flags[2*i] && !flags[2*i+1];
      if i > 0 {
        assert 0 <= i-1 < |flags[2..]| / 2;
        assert flags[2..][2*(i-1)] && !flags[2..][2*(i-1)+1];
        assert IsRed(flags[2..]);
      }
      assert IsRed(flags);
    }
  }
}

method EvaluatePolicy(flags: seq<bool>) returns (violations: seq<bool>, red: bool)
  requires |flags| % 2 == 0
  ensures violations == Violations(flags)
  ensures red == IsRed(flags)
  ensures |violations| * 2 == |flags|
  ensures forall j: int | 0 <= j < |violations| ::
    violations[j] == (flags[2*j] && !flags[2*j+1])
  ensures red <==> (exists j: int | 0 <= j < |flags| / 2 :: flags[2*j] && !flags[2*j+1])
{
  violations := [];
  red := false;
  var i: nat := 0;
  while i < |flags| / 2
    invariant 0 <= i <= |flags| / 2
    invariant |violations| == i
    invariant forall j: int | 0 <= j < i ::
      violations[j] == (flags[2*j] && !flags[2*j+1])
    invariant red <==> (exists j: int | 0 <= j < i :: flags[2*j] && !flags[2*j+1])
    decreases |flags| / 2 - i
  {
    var violation := flags[2*i] && !flags[2*i+1];
    violations := violations + [violation];
    red := red || violation;
    i := i + 1;
  }
  PolicyExact(flags);
  assert violations == Violations(flags);
}

predicate LastAt(s: seq<int>, key: int, index: int) {
  if index == -1 then key !in s
  else (0 <= index < |s| && s[index] == key &&
    (forall j: int :: index < j < |s| ==> s[j] != key))
}

method FindLast(s: seq<int>, key: int) returns (index: int)
  ensures LastAt(s, key, index)
{
  var i := |s|;
  while i > 0
    invariant 0 <= i <= |s|
    invariant forall j: int :: i <= j < |s| ==> s[j] != key
    decreases i
  {
    i := i - 1;
    if s[i] == key {
      index := i;
      return;
    }
  }
  index := -1;
}

method Compute(lab: seq<int>, oracle: seq<int>, size: nat) returns (cells: seq<Cell>)
  requires forall i: int :: 0 <= i < |lab| ==> 0 <= lab[i] < size
  requires forall i: int :: 0 <= i < |oracle| ==> 0 <= oracle[i] < size
  ensures |cells| == size
  ensures forall key: int :: 0 <= key < size ==> Classified(lab, oracle, key, cells[key])
{
  cells := [];
  var key: nat := 0;
  while key < size
    invariant key <= size
    invariant |cells| == key
    invariant forall k: int :: 0 <= k < key ==> Classified(lab, oracle, k, cells[k])
    decreases size - key
  {
    var l := FindLast(lab, key);
    var o := FindLast(oracle, key);
    var kind := if l < 0 then (if o < 0 then 0 else 2) else (if o < 0 then 1 else 3);
    cells := cells + [Cell(l, o, kind)];
    key := key + 1;
  }
}

ghost predicate SeedNode(es: seq<FlowEdge>, seeds: set<int>, hiddenLabel: bool, v: int) {
  v in seeds || (hiddenLabel && (exists u: int :: FlowEdge(u, v, true) in es))
}

ghost predicate Reaches(es: seq<FlowEdge>, seeds: set<int>, hiddenLabel: bool, v: int) {
  exists p: seq<int> :: Walk(es, p) && SeedNode(es, seeds, hiddenLabel, p[0]) && p[|p|-1] == v
}

method Decide(i: Input) returns (verdict: int)
  ensures Policy(i, verdict)
  ensures i.hidden ==> verdict == 0
  ensures i.untrusted && i.privileged && !i.sanitized ==> verdict == 0
{
  if i.hidden {
    verdict := 0;
  } else if i.untrusted && i.privileged && !i.sanitized {
    verdict := 0;
  } else if i.untrusted && i.privileged && i.sanitized {
    verdict := 1;
  } else if i.untrusted && i.sanitized {
    verdict := 2;
  } else if i.untrusted {
    verdict := 1;
  } else {
    verdict := 3;
  }
}

method DecideMany(inputs: seq<Input>) returns (verdicts: seq<int>)
  ensures |verdicts| == |inputs|
  ensures forall n :: 0 <= n < |inputs| ==> Policy(inputs[n], verdicts[n])
  ensures forall n :: 0 <= n < |inputs| && inputs[n].hidden ==> verdicts[n] == 0
  ensures forall n :: (0 <= n < |inputs| && inputs[n].untrusted &&
    inputs[n].privileged && !inputs[n].sanitized) ==> verdicts[n] == 0
{
  verdicts := [];
  var n := 0;
  while n < |inputs|
    invariant 0 <= n <= |inputs|
    invariant |verdicts| == n
    invariant forall j :: 0 <= j < n ==> Policy(inputs[j], verdicts[j])
    invariant forall j :: 0 <= j < n && inputs[j].hidden ==> verdicts[j] == 0
    invariant forall j :: (0 <= j < n && inputs[j].untrusted &&
      inputs[j].privileged && !inputs[j].sanitized) ==> verdicts[j] == 0
    decreases |inputs| - n
  {
    var v := Decide(inputs[n]);
    verdicts := verdicts + [v];
    n := n + 1;
  }
}

method Closure(es: seq<FlowEdge>, seeds: set<int>, hiddenLabel: bool) returns (reached: set<int>)
  ensures forall v :: v in reached <==> Reaches(es,seeds,hiddenLabel,v)
  ensures seeds <= reached
  ensures forall u,v :: u in reached && Link(es,u,v) ==> v in reached
{
  reached := seeds + (if hiddenLabel then HiddenDestinations(es) else {});
  HiddenBound(es);
  forall v | v in reached
    ensures Reaches(es,seeds,hiddenLabel,v)
  {
    HiddenMembership(es,v);
    assert SeedNode(es,seeds,hiddenLabel,v);
    assert Walk(es,[v]);
  }
  forall v | SeedNode(es,seeds,hiddenLabel,v)
    ensures v in reached
  { HiddenMembership(es,v); }
  while true
    invariant seeds <= reached
    invariant reached <= seeds + Vertices(es)
    invariant forall v :: v in reached ==> Reaches(es,seeds,hiddenLabel,v)
    invariant forall v :: SeedNode(es,seeds,hiddenLabel,v) ==> v in reached
    decreases |(seeds + Vertices(es)) - reached|
  {
    var added := Expand(es,reached);
    ExpandBound(es,reached);
    if added <= reached { break; }
    forall v | v in added - reached
      ensures Reaches(es,seeds,hiddenLabel,v)
    {
      ExpandMembership(es,reached,v);
      var u :| u in reached && Link(es,u,v);
      Extend(es,seeds,hiddenLabel,u,v);
    }
    assert reached < reached + added;
    assert (seeds + Vertices(es)) - (reached + added) < (seeds + Vertices(es)) - reached;
    ProperSubsetCardinality((seeds + Vertices(es)) - (reached + added),
                            (seeds + Vertices(es)) - reached);
    reached := reached + added;
  }
  assert forall u,v :: u in reached && Link(es,u,v) ==> v in reached by {
    forall u,v | u in reached && Link(es,u,v)
      ensures v in reached
    { ExpandMembership(es,reached,v); }
  }
  forall v | Reaches(es,seeds,hiddenLabel,v)
    ensures v in reached
  {
    var p :| Walk(es,p) && SeedNode(es,seeds,hiddenLabel,p[0]) && p[|p|-1] == v;
    ClosedWalk(es,p,reached);
  }
}

lemma ReachMonotone(es: seq<FlowEdge>, smaller: set<int>, larger: set<int>, hiddenLabel: bool, v: int)
  requires smaller <= larger && Reaches(es,smaller,hiddenLabel,v)
  ensures Reaches(es,larger,hiddenLabel,v)
{
  var p :| Walk(es,p) && SeedNode(es,smaller,hiddenLabel,p[0]) && p[|p|-1] == v;
  assert SeedNode(es,larger,hiddenLabel,p[0]);
}

lemma ReachWithinEpisode(es: seq<FlowEdge>, seeds: set<int>, hiddenLabel: bool, episode: set<int>, v: int)
  requires seeds <= episode
  requires forall e: FlowEdge :: e in es && e.src in episode ==> e.dst in episode
  requires !hiddenLabel || (forall e: FlowEdge :: e in es && e.hidden ==> e.dst in episode)
  requires Reaches(es,seeds,hiddenLabel,v)
  ensures v in episode
{
  var p :| Walk(es,p) && SeedNode(es,seeds,hiddenLabel,p[0]) && p[|p|-1] == v;
  assert p[0] in episode;
  assert forall u,w :: u in episode && Link(es,u,w) ==> w in episode by {
    forall u,w | u in episode && Link(es,u,w)
      ensures w in episode
    {
      var h :| FlowEdge(u,w,h) in es;
      assert FlowEdge(u,w,h).src == u;
    }
  }
  ClosedWalk(es,p,episode);
}

predicate CompleteCitations(c: Call) {
  c.scope != "" && c.argumentHash != "" && c.sourceCapsule != "" &&
  c.instructionSplit != "" && c.coldReplay != ""
}

predicate BatchSpec(rows: seq<Call>) {
  |rows| == 3 && ExactlyOneWrite(rows) && ExactlyOneUntrusted(rows) &&
    (forall i: int | 0 <= i < |rows| :: Allowed(rows[i]))
}

lemma {:fuel 5} BatchExact(rows: seq<Call>)
  ensures Check(rows) <==> BatchSpec(rows)
  ensures Check(rows) ==> (forall i: int | 0 <= i < |rows| ::
    rows[i].fieldsPresent && CompleteCitations(rows[i]))
{
  if |rows| == 3 {
    RowExact(rows[0]); RowExact(rows[1]); RowExact(rows[2]);
    assert rows == [rows[0], rows[1], rows[2]];
    assert rows[1..] == [rows[1], rows[2]];
    assert rows[2..] == [rows[2]];
    assert rows[3..] == [];
    assert CountWrites(rows) == (if QualifyingWrite(rows[0]) then 1 else 0) + CountWrites(rows[1..]);
    assert CountWrites(rows[1..]) == (if QualifyingWrite(rows[1]) then 1 else 0) + CountWrites(rows[2..]);
    assert CountWrites(rows[2..]) == (if QualifyingWrite(rows[2]) then 1 else 0) + CountWrites(rows[3..]);
    assert CountWrites(rows[3..]) == 0;
    UntrustedStep(rows); UntrustedStep(rows[1..]); UntrustedStep(rows[2..]);
    assert CountUntrusted(rows) == (if rows[0].toolClass == "untrusted_result" then 1 else 0) + CountUntrusted(rows[1..]);
    assert CountUntrusted(rows[1..]) == (if rows[1].toolClass == "untrusted_result" then 1 else 0) + CountUntrusted(rows[2..]);
    assert CountUntrusted(rows[2..]) == (if rows[2].toolClass == "untrusted_result" then 1 else 0) + CountUntrusted(rows[3..]);
    assert CountUntrusted(rows[3..]) == 0;
    assert AllAccepted(rows) == (Accepted(rows[0]) && AllAccepted(rows[1..]));
    assert AllAccepted(rows[1..]) == (Accepted(rows[1]) && AllAccepted(rows[2..]));
    assert AllAccepted(rows[2..]) == (Accepted(rows[2]) && AllAccepted(rows[3..]));
    assert AllAccepted(rows[3..]);
    assert CountWrites(rows) ==
      (if QualifyingWrite(rows[0]) then 1 else 0) +
      (if QualifyingWrite(rows[1]) then 1 else 0) +
      (if QualifyingWrite(rows[2]) then 1 else 0);
    assert CountUntrusted(rows) ==
      (if rows[0].toolClass == "untrusted_result" then 1 else 0) +
      (if rows[1].toolClass == "untrusted_result" then 1 else 0) +
      (if rows[2].toolClass == "untrusted_result" then 1 else 0);
    assert (CountWrites(rows) == 1) <==> ExactlyOneWrite(rows);
    assert (CountUntrusted(rows) == 1) <==> ExactlyOneUntrusted(rows);
    assert AllAccepted(rows) <==> (Allowed(rows[0]) && Allowed(rows[1]) && Allowed(rows[2]));
    assert (forall i: int | 0 <= i < |rows| :: Allowed(rows[i])) <==>
      (Allowed(rows[0]) && Allowed(rows[1]) && Allowed(rows[2]));
  }
}

method Batch(rows: seq<Call>) returns (writes: nat, untrusted: nat, accepted: bool)
  ensures writes == CountWrites(rows)
  ensures untrusted == CountUntrusted(rows)
  ensures accepted == Check(rows)
  ensures accepted ==> (forall i: int | 0 <= i < |rows| ::
    rows[i].fieldsPresent && CompleteCitations(rows[i]))
{
  var i: nat := 0;
  writes := 0;
  untrusted := 0;
  var ok := true;
  while i < |rows|
    invariant i <= |rows|
    invariant writes + CountWrites(rows[i..]) == CountWrites(rows)
    invariant untrusted + CountUntrusted(rows[i..]) == CountUntrusted(rows)
    invariant (ok && AllAccepted(rows[i..])) == AllAccepted(rows)
    decreases |rows| - i
  {
    assert rows[i..][0] == rows[i];
    assert rows[i..][1..] == rows[i+1..];
    if QualifyingWrite(rows[i]) { writes := writes + 1; }
    if rows[i].toolClass == "untrusted_result" { untrusted := untrusted + 1; }
    ok := ok && Accepted(rows[i]);
    i := i + 1;
  }
  accepted := |rows| == 3 && writes == 1 && untrusted == 1 && ok;
  BatchExact(rows);
}

predicate MatchSpec(p: string, s: string) {
  if |p| > 0 && p[|p|-1] == '*' then
    |s| >= |p|-1 && s[..|p|-1] == p[..|p|-1]
  else p == s
}

predicate FoundSpec(p: string, selected: seq<string>) {
  exists j :: 0 <= j < |selected| && MatchSpec(p, selected[j])
}

predicate RelevantSpec(s: string, expected: seq<string>) {
  exists j :: 0 <= j < |expected| && MatchSpec(expected[j], s)
}

function Latency(timeout: bool, wall: int, budget: int): int {
  if timeout then 2 else if wall <= budget then 0 else 1
}

lemma CountsAreCardinalities(e: seq<string>, s: seq<string>, a: nat, b: nat)
  requires a <= |e| && b <= |s|
  ensures FoundCount(e,s,a) == |FoundIndices(e,s,a)|
  ensures RelevantCount(e,s,b) == |RelevantIndices(e,s,b)|
  decreases a+b
{
  if a > 0 {
    CountsAreCardinalities(e,s,a-1,b);
    AnySelectedExact(e[a-1],s,|s|);
    assert FoundIndices(e,s,a) == FoundIndices(e,s,a-1) +
      (if FoundSpec(e[a-1],s) then {a-1} else {});
    assert a-1 !in FoundIndices(e,s,a-1);
  } else if b > 0 {
    CountsAreCardinalities(e,s,a,b-1);
    AnyExpectedExact(s[b-1],e,|e|);
    assert RelevantIndices(e,s,b) == RelevantIndices(e,s,b-1) +
      (if RelevantSpec(s[b-1],e) then {b-1} else {});
    assert b-1 !in RelevantIndices(e,s,b-1);
  }
}

method Compute(e: seq<string>, s: seq<string>, t: bool, err: bool,
               scent: bool, forbidden: bool, wall: int, budget: int)
    returns (flags: seq<bool>, found: nat, relevant: nat, decision: int, latency: int)
  ensures |flags| == |e|
  ensures forall i :: 0 <= i < |e| ==> (flags[i] <==> FoundSpec(e[i],s))
  ensures found == |FoundIndices(e,s,|e|)|
  ensures relevant == |RelevantIndices(e,s,|s|)|
  ensures found <= |e| && relevant <= |s|
  ensures DecisionSpec(t,err,found < |e|,scent,forbidden,decision)
  ensures latency == Latency(t,wall,budget)
  ensures latency == 2 <==> t
  ensures !t ==> (latency == 0 <==> wall <= budget)
{
  flags := []; found := 0; relevant := 0;
  var i: nat := 0;
  while i < |e|
    invariant i <= |e| && |flags| == i
    invariant found == FoundCount(e,s,i)
    invariant forall j :: 0 <= j < i ==> (flags[j] <==> AnySelected(e[j],s,|s|))
    decreases |e|-i
  {
    var hit := HasSelected(e[i],s);
    flags := flags + [hit];
    if hit { found := found + 1; }
    i := i + 1;
  }
  var j: nat := 0;
  while j < |s|
    invariant j <= |s|
    invariant relevant == RelevantCount(e,s,j)
    decreases |s|-j
  {
    var hit := HasExpected(s[j],e);
    if hit { relevant := relevant + 1; }
    j := j + 1;
  }
  ExactAndBounded(e,s);
  CountsAreCardinalities(e,s,|e|,|s|);
  DecisionExact(t,err,found < |e|,scent,forbidden,wall,budget);
  decision := Decision(t,err,found < |e|,scent,forbidden);
  latency := Latency(t,wall,budget);
}

predicate SelectedPrefix(claims: seq<Claim>, path: int, n: nat, owner: int)
  requires n <= |claims|
{
  if owner == -1 then (forall j: int :: 0 <= j < n ==> claims[j].path != path)
  else (0 <= owner < n && claims[owner].path == path &&
    (forall j: int :: 0 <= j < n && claims[j].path == path ==>
      Priority(claims[j].freshness) <= Priority(claims[owner].freshness)) &&
    (forall j: int :: 0 <= j < owner && claims[j].path == path ==>
      Priority(claims[j].freshness) < Priority(claims[owner].freshness)))
}

predicate HasLive(claims: seq<Claim>, path: int) {
  exists j: int :: 0 <= j < |claims| && claims[j].path == path && claims[j].freshness == Live
}

predicate ClassificationSpec(rows: seq<Row>, c: int) {
  var live := exists i: int :: 0 <= i < |rows| && rows[i].kind == 2;
  var unknown := exists i: int :: 0 <= i < |rows| && rows[i].kind == 5;
  var stale := exists i: int :: 0 <= i < |rows| && rows[i].kind == 3;
  var unowned := exists i: int :: 0 <= i < |rows| && rows[i].kind == 1;
  (live && c == 2) || (!live && unknown && c == 5) ||
  (!live && !unknown && stale && c == 3) ||
  (!live && !unknown && !stale && unowned && c == 1) ||
  (!live && !unknown && !stale && !unowned && |rows| > 0 && c == 4) ||
  (|rows| == 0 && c == 0)
}

predicate ActionSpec(c: int, action: int) {
  (c == 2 && action == 11) || (c == 5 && action == 16) ||
  (c == 3 && action == 12) || (c == 1 && action == 13) ||
  (c == 4 && action == 14) || (c == 0 && action == 15)
}

method FindOwner(claims: seq<Claim>, path: int) returns (owner: int)
  ensures SelectedPrefix(claims, path, |claims|, owner)
{
  owner := -1;
  var i: nat := 0;
  while i < |claims|
    invariant i <= |claims|
    invariant SelectedPrefix(claims, path, i, owner)
    invariant forall j: int :: 0 <= j < i && claims[j].path == path ==> claims[j].freshness != Live
    decreases |claims| - i
  {
    if claims[i].path == path {
      if claims[i].freshness == Live {
        owner := i;
        return;
      }
      if owner < 0 || Priority(claims[i].freshness) > Priority(claims[owner].freshness) {
        owner := i;
      }
    }
    i := i + 1;
  }
}

method Compute(paths: seq<Path>, claims: seq<Claim>)
    returns (rows: seq<Row>, classification: int, action: int)
  ensures |rows| == |paths|
  ensures forall i: int :: 0 <= i < |paths| ==> RowSpec(paths[i], claims, rows[i])
  ensures forall i: int :: 0 <= i < |paths| ==> (rows[i].kind == 2 <==> paths[i].generated && HasLive(claims, paths[i].id))
  ensures ClassificationSpec(rows, classification)
  ensures ActionSpec(classification, action)
  ensures (exists i: int :: 0 <= i < |paths| && paths[i].generated && HasLive(claims, paths[i].id)) ==>
    classification == 2 && action == 11
{
  rows := [];
  var live, unknown, stale, unowned := false, false, false, false;
  var i: nat := 0;
  while i < |paths|
    invariant i <= |paths| && |rows| == i
    invariant forall j: int :: 0 <= j < i ==> RowSpec(paths[j], claims, rows[j])
    invariant live <==> (exists j: int :: 0 <= j < i && rows[j].kind == 2)
    invariant unknown <==> (exists j: int :: 0 <= j < i && rows[j].kind == 5)
    invariant stale <==> (exists j: int :: 0 <= j < i && rows[j].kind == 3)
    invariant unowned <==> (exists j: int :: 0 <= j < i && rows[j].kind == 1)
    decreases |paths| - i
  {
    var row := Row(-1, 0);
    if paths[i].generated {
      var owner := FindOwner(claims, paths[i].id);
      row := if owner < 0 then Row(-1, 1)
        else if claims[owner].freshness == Live then Row(owner, 2)
        else if claims[owner].freshness == Unknown then Row(owner, 5) else Row(owner, 3);
    }
    assert RowSpec(paths[i], claims, row);
    rows := rows + [row];
    live := live || row.kind == 2;
    unknown := unknown || row.kind == 5;
    stale := stale || row.kind == 3;
    unowned := unowned || row.kind == 1;
    i := i + 1;
  }
  forall j | 0 <= j < |paths| { LiveRowExact(paths[j], claims, rows[j]); }
  classification := if live then 2 else if unknown then 5 else if stale then 3
    else if unowned then 1 else if |rows| > 0 then 4 else 0;
  action := if classification == 2 then 11 else if classification == 5 then 16
    else if classification == 3 then 12 else if classification == 1 then 13
    else if classification == 4 then 14 else 15;
}

ghost function OverlapSpec(q: seq<nat>, p: seq<nat>): nat
  requires |q| == |p|
  decreases |q|
{
  if |q| == 0 then 0 else (if q[0] <= p[0] then q[0] else p[0]) + OverlapSpec(q[1..], p[1..])
}

ghost function ScoreSpec(q: seq<nat>, c: Candidate): nat
  requires |q| == |c.counts|
{ OverlapSpec(q, c.counts) + (if c.bonus then 1 else 0) }

ghost predicate RankBefore(a: Entry, b: Entry) {
  a.score >= b.score && (a.score != b.score ||
    (a.idRank <= b.idRank && (a.idRank != b.idRank || a.index <= b.index)))
}

method Score(q: seq<nat>, p: seq<nat>, bonus: bool) returns (v: nat)
  requires |q| == |p|
  ensures v == OverlapSpec(q,p) + (if bonus then 1 else 0)
{
  var i := |q|;
  v := if bonus then 1 else 0;
  while i > 0
    invariant 0 <= i <= |q|
    invariant v == OverlapSpec(q[i..],p[i..]) + (if bonus then 1 else 0)
    decreases i
  {
    i := i - 1;
    v := v + (if q[i] <= p[i] then q[i] else p[i]);
  }
}

method Insert(s: seq<Entry>, x: Entry) returns (t: seq<Entry>)
  requires Ordered(s)
  ensures Ordered(t)
  ensures multiset(t) == multiset(s) + multiset{x}
{
  var i := 0;
  while i < |s| && !Before(x, s[i])
    invariant 0 <= i <= |s|
    invariant forall j :: 0 <= j < i ==> Before(s[j], x)
    decreases |s| - i
  {
    assert Before(s[i], x);
    i := i + 1;
  }
  t := s[..i] + [x] + s[i..];
  assert s == s[..i] + s[i..];
  assert multiset(t) == multiset(s[..i]) + multiset{x} + multiset(s[i..]);
  assert forall j :: i <= j < |s| ==> Before(x, s[j]) by {
    forall j | i <= j < |s| ensures Before(x, s[j]) {
      if j > i { assert RankBefore(s[i], s[j]); }
    }
  }
  assert Ordered(t) by {
    forall j, k | 0 <= j < k < |t| ensures RankBefore(t[j], t[k]) {
      if k < i {
        assert t[j] == s[j] && t[k] == s[k];
      } else if k == i {
        assert t[j] == s[j] && t[k] == x;
      } else if j == i {
        assert t[j] == x && t[k] == s[k - 1];
      } else if j < i {
        assert t[j] == s[j] && t[k] == s[k - 1];
      } else {
        assert t[j] == s[j - 1] && t[k] == s[k - 1];
      }
    }
  }
}

method Compute(q: seq<nat>, cs: seq<Candidate>) returns (out: seq<Entry>)
  requires forall i :: 0 <= i < |cs| ==> |cs[i].counts| == |q|
  ensures Ordered(out)
  ensures multiset(out) == Expected(q,cs,|cs|)
{
  out := [];
  var i := 0;
  while i < |cs|
    invariant 0 <= i <= |cs|
    invariant Ordered(out)
    invariant multiset(out) == Expected(q,cs,i)
    decreases |cs| - i
  {
    if cs[i].eligible {
      var v := Score(q,cs[i].counts,cs[i].bonus);
      out := Insert(out, Entry(i,cs[i].idRank,v));
    }
    i := i + 1;
  }
}

